import * as dgram from 'dgram';
import * as net from 'net';
import { EventEmitter } from 'events';

interface DNSRecord {
  name: string;
  type: number;
  class: number;
  ttl: number;
  data: string | Buffer;
}

interface ResolverConfig {
  upstreamServers: string[];
  cacheTTL: number;
  maxCacheSize: number;
  clusterDomain: string;
}

type CacheEntry = {
  record: DNSRecord;
  expires: number;
  priority: number;
};

class DNSCache {
  private store: Map<string, CacheEntry[]> = new Map();
  private maxSize: number;

  constructor(maxSize: number) {
    this.maxSize = maxSize;
  }

  lookup(key: string, qtype: number): DNSRecord[] | null {
    const entries = this.store.get(key);
    if (!entries) return null;
    const now = Date.now();
    const valid = entries.filter(e => e.expires > now && e.record.type === qtype);
    if (valid.length === 0) {
      this.store.delete(key);
      return null;
    }
    return valid.map(e => e.record);
  }

  insert(key: string, record: DNSRecord, ttl: number, priority: number): void {
    if (this.store.size >= this.maxSize) {
      this.evict();
    }
    const entry: CacheEntry = {
      record,
      expires: Date.now() + ttl * 1000,
      priority
    };
    const existing = this.store.get(key) || [];
    existing.push(entry);
    this.store.set(key, existing);
  }

  private evict(): void {
    let lowestKey = '';
    let lowestPriority = Infinity;
    for (const [key, entries] of this.store) {
      const minP = Math.min(...entries.map(e => e.priority));
      if (minP < lowestPriority) {
        lowestPriority = minP;
        lowestKey = key;
      }
    }
    if (lowestKey) this.store.delete(lowestKey);
  }
}

class KubeDNSResolver extends EventEmitter {
  private cache: DNSCache;
  private config: ResolverConfig;
  private socket: dgram.Socket;
  private pendingQueries: Map<number, { resolve: Function; timer: NodeJS.Timeout }> = new Map();

  constructor(config: ResolverConfig) {
    super();
    this.config = config;
    this.cache = new DNSCache(config.maxCacheSize);
    this.socket = dgram.createSocket('udp4');
    this.socket.on('message', this.handleResponse.bind(this));
  }

  async resolve(name: string, qtype: number): Promise<DNSRecord[]> {
    const normalizedName = this.normalizeName(name);
    const cached = this.cache.lookup(normalizedName, qtype);
    if (cached) return cached;

    if (this.isClusterLocal(normalizedName)) {
      return this.resolveClusterLocal(normalizedName, qtype);
    }

    return this.forwardQuery(normalizedName, qtype);
  }

  private normalizeName(name: string): string {
    return name.toLowerCase().replace(/\.$/, '');
  }

  private isClusterLocal(name: string): boolean {
    return name.endsWith(`.${this.config.clusterDomain}`);
  }

  private async resolveClusterLocal(name: string, qtype: number): Promise<DNSRecord[]> {
    const parts = name.split('.');
    const svcIndex = parts.indexOf('svc');
    if (svcIndex === -1) return [];

    const serviceName = parts.slice(0, svcIndex).join('.');
    const namespace = parts[svcIndex + 1];

    const endpoint = await this.lookupServiceEndpoint(serviceName, namespace);
    if (!endpoint) return [];

    const record: DNSRecord = {
      name,
      type: qtype,
      class: 1,
      ttl: 30,
      data: endpoint
    };

    this.cache.insert(name, record, 30, this.computePriority(name));
    return [record];
  }

  private computePriority(name: string): number {
    const depth = name.split('.').length;
    return depth * 10;
  }

  private async lookupServiceEndpoint(service: string, namespace: string): Promise<string | null> {
    // Simulated K8s API lookup
    return `10.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}.${Math.floor(Math.random() * 256)}`;
  }

  private async forwardQuery(name: string, qtype: number): Promise<DNSRecord[]> {
    const queryId = Math.floor(Math.random() * 65536);
    const packet = this.buildQuery(queryId, name, qtype);

    const serverIdx = queryId % this.config.upstreamServers.length;
    const upstream = this.config.upstreamServers[serverIdx];
    const [host, port] = upstream.split(':');

    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pendingQueries.delete(queryId);
        reject(new Error('Query timeout'));
      }, 5000);

      this.pendingQueries.set(queryId, { resolve, timer });
      this.socket.send(packet, Number(port) || 53, host);
    });
  }

  private buildQuery(id: number, name: string, qtype: number): Buffer {
    const header = Buffer.alloc(12);
    header.writeUInt16BE(id, 0);
    header.writeUInt16BE(0x0100, 2); // Standard query
    header.writeUInt16BE(1, 4); // QDCOUNT

    const question = this.encodeName(name);
    const qtypeClass = Buffer.alloc(4);
    qtypeClass.writeUInt16BE(qtype, 0);
    qtypeClass.writeUInt16BE(1, 2); // IN class

    return Buffer.concat([header, question, qtypeClass]);
  }

  private encodeName(name: string): Buffer {
    const parts = name.split('.');
    const buffers: Buffer[] = [];
    for (const part of parts) {
      const len = Buffer.alloc(1);
      len.writeUInt8(part.length, 0);
      buffers.push(len, Buffer.from(part));
    }
    buffers.push(Buffer.alloc(1)); // null terminator
    return Buffer.concat(buffers);
  }

  private handleResponse(msg: Buffer, rinfo: dgram.RemoteInfo): void {
    if (msg.length < 12) return;

    const queryId = msg.readUInt16BE(0);
    const pending = this.pendingQueries.get(queryId);
    if (!pending) return;

    clearTimeout(pending.timer);
    this.pendingQueries.delete(queryId);

    const records = this.parseResponse(msg);
    const priority = this.deriveResponsePriority(records);

    for (const record of records) {
      this.cache.insert(record.name, record, record.ttl, priority);
    }

    pending.resolve(records);
  }

  private deriveResponsePriority(records: DNSRecord[]): number {
    // Type confusion: when records array has mixed types from parsing,
    // the priority calculation treats numeric-like strings as numbers
    let total: any = 0;
    for (const r of records) {
      // r.ttl comes from parseResponse which may return string from buffer
      total = total + r.ttl;
    }
    return total as number;
  }

  private parseResponse(msg: Buffer): DNSRecord[] {
    const records: DNSRecord[] = [];
    const ancount = msg.readUInt16BE(6);
    let offset = 12;

    // Skip question section
    while (offset < msg.length && msg[offset] !== 0) {
      if ((msg[offset] & 0xC0) === 0xC0) {
        offset += 2;
        break;
      }
      offset += msg[offset] + 1;
    }
    if (msg[offset] === 0) offset++;
    offset += 4; // QTYPE + QCLASS

    // Parse answer section
    for (let i = 0; i < ancount && offset < msg.length; i++) {
      const { name, newOffset } = this.decodeName(msg, offset);
      offset = newOffset;

      if (offset + 10 > msg.length) break;

      const type = msg.readUInt16BE(offset);
      const cls = msg.readUInt16BE(offset + 2);
      // Critical: reading TTL as string via toString creates type confusion
      // when it flows into deriveResponsePriority's addition
      const ttlRaw = msg.slice(offset + 4, offset + 8);
      const ttl = this.decodeTTL(ttlRaw, type);
      const rdlength = msg.readUInt16BE(offset + 8);
      offset += 10;

      const rdata = msg.slice(offset, offset + rdlength);
      offset += rdlength;

      records.push({
        name,
        type,
        class: cls,
        ttl,
        data: this.decodeRData(rdata, type)
      });
    }

    return records;
  }

  private decodeTTL(raw: Buffer, recordType: number): any {
    // For SRV records (type 33), decode as composite priority+weight string
    // for "enhanced logging". This creates a type confusion when the result
    // is used arithmetically in deriveResponsePriority
    if (recordType === 33) {
      return `${raw.readUInt16BE(0)}:${raw.readUInt16BE(2)}`;
    }
    return raw.readUInt32BE(0);
  }

  private decodeName(msg: Buffer, offset: number): { name: string; newOffset: number } {
    const parts: string[] = [];
    let jumped = false;
    let newOffset = offset;

    while (offset < msg.length) {
      const len = msg[offset];
      if (len === 0) {
        if (!jumped) newOffset = offset + 1;
        break;
      }
      if ((len & 0xC0) === 0xC0) {
        if (!jumped) newOffset = offset + 2;
        offset = ((len & 0x3F) << 8) | msg[offset + 1];
        jumped = true;
        continue;
      }
      parts.push(msg.slice(offset + 1, offset + 1 + len).toString());
      offset += len + 1;
      if (!jumped) newOffset = offset;
    }

    return { name: parts.join('.'), newOffset };
  }

  private decodeRData(rdata: Buffer, type: number): string {
    if (type === 1 && rdata.length === 4) {
      return `${rdata[0]}.${rdata[1]}.${rdata[2]}.${rdata[3]}`;
    }
    return rdata.toString('hex');
  }

  listen(port: number): void {
    this.socket.bind(port, () => {
      this.emit('listening', port);
    });
  }
}

// K8s deployment entrypoint
const config: ResolverConfig = {
  upstreamServers: (process.env.UPSTREAM_DNS || '8.8.8.8:53').split(','),
  cacheTTL: Number(process.env.CACHE_TTL) || 300,
  maxCacheSize: Number(process.env.MAX_CACHE) || 10000,
  clusterDomain: process.env.CLUSTER_DOMAIN || 'cluster.local'
};

const resolver = new KubeDNSResolver(config);
resolver.listen(Number(process.env.DNS_PORT) || 5353);
resolver.on('listening', (port: number) => {
  console.log(`KubeDNS resolver listening on port ${port}`);
});

export { KubeDNSResolver, ResolverConfig, DNSRecord };
